-- =============================================================================
-- Akademi kaynak sicili seed V1 — ADAY kayıtlar (status=candidate).
-- =============================================================================
-- docs/academy/sources_candidates.json'dan üretildi (113 aday; probe raporu
-- docs/academy/source_verification.json). ADAY != aktif: worker gerçek
-- makale çıkarımını kanıtlayınca status=active olur. Aynı yayıncı grubu
-- publisher_group ile işaretlidir (bağımsız teyit SAYILMAZ). Idempotent.

-- Bot–kaynak eşleştirme: kaynak konuları → bot anahtarı (idempotent).
-- ASAMA-1 eki (2026-09-29): zayif konulara 16 yeni aday (isletme/turk_urunleri/ustalik_dunya).


select t.topic, s.id, 100
from public.academy_sources s
cross join lateral unnest(s.topics) as t(topic)
join public.academy_bot_profiles b on b.bot_key = t.topic
on conflict (bot_key, source_id) do nothing;
